13: // Numerical contract is frozen in CONTRACT.json. No fast-math permitted.
14: 
15: // IEEE binary128 is used only for cancellation control in the newly admitted
16: // compact complex strip. Every series recurrence coefficient is formed in
17: // binary128. Basic arithmetic is provided by libgcc; no quad transcendental is
18: // required.  Original longdouble paths remain bit-for-bit unchanged.
19: #if !defined(__SIZEOF_FLOAT128__) || __FLT128_MANT_DIG__ != 113
20: #error "IEEE binary128 basic arithmetic is required for the wide strip"
21: #endif
22: #if defined(__FAST_MATH__) || (defined(__FINITE_MATH_ONLY__) && __FINITE_MATH_ONLY__)
23: #error "Strict floating point required"
24: #endif
25: using Q=__float128;
26: struct QZ {Q r,i;};
27: static Q qa(Q x){return x<0?-x:x;}
28: static Q qnorm(QZ x){return qa(x.r)+qa(x.i);}
29: static QZ qadd(QZ a,QZ b){return {a.r+b.r,a.i+b.i};}
30: static QZ qsub(QZ a,QZ b){return {a.r-b.r,a.i-b.i};}
31: static QZ qmul(QZ a,QZ b){return {a.r*b.r-a.i*b.i,a.r*b.i+a.i*b.r};}
32: static QZ qscale(QZ a,Q b){return {a.r*b,a.i*b};}
33: static int hypergeom_wide(R a,R b,Z z,Z &out){
34:     QZ term{1,0},sum{1,0},correction{0,0};
35:     const QZ zz{Q(z.real()),Q(z.imag())};
36:     const Q eps=Q(ldexpl(1.L,-112));
37:     for(int k=1;k<=1024;++k){
38:         const Q ratio=(Q(a)+k-1)/((Q(b)+k-1)*k);
39:         term=qscale(qmul(term,zz),ratio);
40:         const QZ y=qsub(term,correction),updated=qadd(sum,y);
41:         correction=qsub(qsub(updated,sum),y);sum=updated;
42:         if(Q(k)+a>0){
43:             Q fac=(Q(k)+a)/(Q(k)+b);if(fac<1)fac=1;
44:             const Q q=qnorm(zz)/(k+1)*fac;
45:             // The l1 complex norm is submultiplicative. For subsequent terms,
46:             // max(1,(k+a)/(k+b)) and 1/(k+1) bound all future ratios.
47:             if(q<1 && qnorm(term)*q/(1-q)<=eps*qnorm(sum)/8){
48:                 out=Z(R(sum.r),R(sum.i));return k;
49:             }
50:         }
51:     }
52:     return -1;
53: }
