133: extern "C" int radial_entire(std::size_t n,const R* variance,const R* sr,const R* si,
134:                             int order,R* output,int* maximum_iterations) {
135:     if(!maximum_iterations)return -4;
136:     *maximum_iterations=0;
137:     if(order<0 || order>2)return -4;
138:     if(n>std::size_t(std::numeric_limits<std::ptrdiff_t>::max())/(60*sizeof(R)))return -4;
139:     if(n>0 && (!variance || !sr || !si || !output))return -4;
140:     if(std::fegetround()!=FE_TONEAREST)return -5;
141:     // All inputs are validated before any output is written, including batched failures.
142:     for(std::size_t i=0;i<n;++i) {
143:       const R v=variance[i];
144:       if(!std::isfinite(v)||v<1e-100L||v>1e100L ||
145:          !std::isfinite(sr[i])||!std::isfinite(si[i]))return -2;
146:       const Z x(sr[i]/(2*v),si[i]/(2*v));
147:       if(!std::isfinite(x.real())||!std::isfinite(x.imag())||
148:          x.real() < -32 || x.real()>1e12L || fabsl(x.imag())>32)return -2;

150:     static const R pi=acosl(-1.L),rootpi=sqrtl(pi);
151:     static const R gamma_ratio[10]={2/rootpi,1,2/rootpi,R(1.5L),4/rootpi,R(3.75L),
152:                             12/rootpi,R(13.125L),48/rootpi,R(59.0625L)};
153:     int maxiter=0;
154:     for(std::size_t i=0;i<n;++i) {
155:         const R v=variance[i];
156:         const Z x(sr[i]/(2*v),si[i]/(2*v));
157:         if(!(v>0) || !std::isfinite(v) || !std::isfinite(x.real()) || !std::isfinite(x.imag())
158:            || x.real() < -32 || x.real()>1e12L || fabsl(x.imag())>32) return -2;
159:         Z positive[3][5];
160:         if(x.real()>=-0.5L) {
161:           int it=positive_odd(v,x,order,positive);
162:           if(it<0)return -1;
163:           if(it>maxiter)maxiter=it;
164:         }
165:         // All needed powers are integer recurrences from one square root.
166:         // Shared-seed odd moments already exist; their generic constants are unused.
167:         const R twice_v=2*v;
168:         R powers[10];powers[1]=1;
169:         for(int idx=3;idx<10;idx+=2)powers[idx]=powers[idx-2]*twice_v;
170:         const bool shared=x.real()>=-0.5L;
171:         if(!shared) {
172:           powers[0]=1/sqrtl(twice_v);
173:           for(int idx=2;idx<10;idx+=2)powers[idx]=powers[idx-2]*twice_v;
174:         }
175:         for(int p=-1;p<=8;++p) {
176:             const bool is_shared_odd=shared && (p==-1 || p%2==1);
177:             const R constant=is_shared_odd ? R(0) : powers[p+1]*gamma_ratio[p+1];
178:             for(int j=0;j<=order;++j) {
179:                 R prefactor=constant;
180:                 if(j==1) prefactor*=R(p)/(6*v);
181:                 if(j==2) prefactor*=R(p*(p-2))/(60*v*v);
182:                 Z out(0,0);
183:                 if((p==-1 || p%2==1) && x.real()>=-0.5L) out=positive[j][(p+1)/2];
184:                 else if(prefactor!=0) {
185:                     const R a=R(j)-R(p)/2,b=R(1.5L)+j;
186:                     if(p>=0 && p%2==0) out=polynomial(a,b,-x,p/2-j);
187:                     else {
188:                         const bool kummer=x.real()>0;
189:                         const int it=hypergeom(kummer?R(p+3)/2:a,b,kummer?x:-x,out);
190:                         if(it<0) return -1;
191:                         if(it>maxiter) maxiter=it;
192:                         if(kummer) out*=std::exp(-x);
193:                     }
194:                     out*=prefactor;
195:                 }
196:                 if(!std::isfinite(out.real()) || !std::isfinite(out.imag())) return -3;
197:                 const std::size_t loc=2*((std::size_t(j)*10+(p+1))*n+i);
198:                 output[loc]=out.real();output[loc+1]=out.imag();

